exercises.tests:
RESULTS = [{"name": "t1", "duration_ms": 120}, {"name": "t2", "duration_ms": 45}, {"name": "t3", "duration_ms": 300}]


def test_sorted_names_by_duration():
    assert sorted_names_by_duration(RESULTS) == ["t2", "t1", "t3"], "имена должны идти в порядке возрастания duration_ms"


def test_slow_tests_default_threshold():
    result = slow_tests(RESULTS)
    names = [r["name"] for r in result]
    assert names == ["t1", "t3"], f"должны остаться только тесты с duration_ms > 100: {names}"


def test_slow_tests_custom_threshold():
    result = slow_tests(RESULTS, threshold=200)
    names = [r["name"] for r in result]
    assert names == ["t3"], f"с порогом 200 должен остаться только t3: {names}"


def test_has_test_longer_than_true():
    assert has_test_longer_than(RESULTS, 250) is True, "t3 длится 300 мс, что больше 250"


def test_has_test_longer_than_false():
    assert has_test_longer_than(RESULTS, 1000) is False, "ни один тест не длится дольше 1000 мс"

