def test_first_sum_correct():
    result = sum_twice([1, 2, 3])
    assert result[0] == 12, "первая сумма должна быть суммой удвоенных чисел: (1+2+3)*2 = 12"


def test_second_sum_is_exhausted():
    result = sum_twice([1, 2, 3])
    assert result[1] == 0, "map-объект уже пройден один раз функцией sum() и исчерпан - повторный проход должен дать 0"


def test_returns_tuple():
    result = sum_twice([5])
